def add(story, sections):
    for heading, body in sections:
        story += [Paragraph(heading, S["heading"]), Paragraph(body, S["body"])]

def build():
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    doc = SimpleDocTemplate(str(OUTPUT), pagesize=A4, leftMargin=52, rightMargin=52, topMargin=42, bottomMargin=38, title="รายงานทดสอบต้นแบบแอปพร้อมวิ่ง")
    story = []
    for i, tester in enumerate(TESTERS):
        story += [Paragraph('งาน “การทดสอบ User 2 รายต่อคน”', S["title"]), Paragraph("เขียนรายงานสรุป คนละ 1 ฉบับเป็นคะแนนเก็บ", S["subtitle"])]
        add(story, COMMON + tester["top"])
        story.append(PageBreak())
        add(story, tester["bottom"] + [("10. ข้อมูลส่วนอื่น ๆ", tester["other"])])
        if i == 0:
            story.append(PageBreak())
    doc.build(story)
    print(OUTPUT)

if __name__ == "__main__":
    build()
